            0x01: 0x0220,  # CONFIG
            0x02: 0x6000,  # THIGH
            0x03: 0x8000,  # TLOW
            0x04: 0x0000,  # EEPROM_UL
            0x05: 0x0000,  # EEPROM1
            0x06: 0x0000,  # EEPROM2
            0x07: 0x0000,  # TEMP_OFFSET
            0x08: 0x0000,  # EEPROM3
            0x0F: 0x0117,  # DEVICE_ID
        }

    def read_register(self, addr: int, nbytes: int = 2) -> int:
        if addr not in self.regs:
            raise ValueError(f"Invalid register address: {addr:#04x}")

        value = self.regs[addr]

        if nbytes == 1:
            value >>= 8

        # Clear read-to-clear flags
        if addr == 0x01:  # CONFIG
            self.regs[0x01] &= ~(0x3FFF)  # Clear HIGH_ALERT, LOW_ALERT, DATA_READY

        return value & ((1 << (nbytes * 8)) - 1)

    def write_register(self, addr: int, data: int, nbytes: int = 2) -> None:
        if addr not in self.regs:
            raise ValueError(f"Invalid register address: {addr:#04x}")

        if nbytes == 1:
            mask = 0xFF00 if (data & 0x80) else 0x00FF
            data <<= 8 if (data & 0x80) else 0
            data &= mask
            self.regs[addr] = (self.regs[addr] & ~mask) | data
        else:
            self.regs[addr] = data

        # Handle specific write behaviors
        if addr == 0x01:  # CONFIG
            if data & (1 << 1):  # Soft Reset bit
                self.regs[0x01] = 0x0220  # Reset to default value

