        0x06: {'name': 'EEPROM2', 'access': 'RW', 'reset': 0x0000},
        0x07: {'name': 'TEMP_OFFSET', 'access': 'RW', 'reset': 0x0000},
        0x08: {'name': 'EEPROM3', 'access': 'RW', 'reset': 0x0000},
        0x0F: {'name': 'DEVICE_ID', 'access': 'RO', 'reset': 0x0117},
    }

    def __init__(self):
        super().__init__()
        for addr, reg in self.REGISTERS.items():
            self.regs[addr] = reg['reset']

    def read_register(self, addr: int, nbytes: int = 2) -> int:
        if addr not in self.regs:
            raise ValueError(f"Invalid register address: {hex(addr)}")

